{
  "findings": [
    {
      "check_id": "CKV_AWS_84",
      "title": "Ensure Elasticsearch Domain Logging is enabled",
      "resource": "aws_elasticsearch_domain.log_search_database",
      "severity": "MEDIUM",
      "explanation": "The resource does not define a log_publishing_options block, meaning audit and application logs are not being published to CloudWatch Logs or S3, hindering security monitoring and incident response."
    },
    {
      "check_id": "CKV_AWS_228",
      "title": "Verify Elasticsearch domain is using an up to date TLS policy",
      "resource": "aws_elasticsearch_domain.log_search_database",
      "severity": "MEDIUM",
      "explanation": "The domain_name 'enterprise-log-analytics-es' suggests this is a production environment. The configuration lacks an explicit domain_endpoint_options block with a secure TLS policy (e.g., Policy-Min-TLS-1-2-2019-07), potentially allowing connections via deprecated and insecure TLS versions."
    },
    {
      "check_id": "CKV_AWS_25",
      "title": "Ensure all data stored in the Elasticsearch is securely encrypted at rest",
      "resource": "aws_elasticsearch_domain.log_search_database",
      "severity": "HIGH",
      "explanation": "The encrypt_at_rest block explicitly sets enabled = false. This leaves sensitive enterprise log data unencrypted on EBS volumes, violating standard data protection requirements."
    }
  ],
  "patched_code": "resource "aws_elasticsearch_domain" "log_search_database" {
  domain_name           = "enterprise-log-analytics-es"
  elasticsearch_version = "7.10"
  cluster_config {
    instance_type  = var.elasticsearch_instance_type
    instance_count = 2
  }
  vpc_options {
    subnet_ids         = [aws_subnet.data_subnet_az1.id]
    security_group_ids = [aws_security_group.elasticsearch_sg.id]
  }
  ebs_options {
    ebs_enabled = true
    volume_size = 20
    volume_type = "gp2"
  }
  encrypt_at_rest {
    enabled = true
  }
  domain_endpoint_options {
    enforce_https       = true
    tls_security_policy = "Policy-Min-TLS-1-2-2019-07"
  }
  log_publishing_options {
    cloudwatch_log_group_arn = aws_cloudwatch_log_group.es_logs.arn
    log_type                 = "INDEX_SLOW_LOGS"
  }
  log_publishing_options {
    cloudwatch_log_group_arn = aws_cloudwatch_log_group.es_logs.arn
    log_type                 = "SEARCH_SLOW_LOGS"
  }
}

resource "aws_cloudwatch_log_group" "es_logs" {
  name              = "/aws/es/enterprise-log-analytics-es"
  retention_in_days = 365
}",
  "fix_summary": "Enabled encryption at rest by setting `enabled = true`. Added `domain_endpoint_options` to enforce HTTPS and use a modern TLS security policy. Added `log_publishing_options` for INDEX_SLOW_LOGS and SEARCH_SLOW_LOGS along with a supporting `aws_cloudwatch_log_group` resource to enable observability logging."
}
